class GSLMatrix(object):
    def __init__(self, rows, cols):
        self.matrix = gsl.gsl_matrix_alloc(rows, cols)

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)

# Functions
def numpy_to_gsl_matrix(np_array):
    gsl_matrix = GSLMatrix(np_array.shape[0], np_array.shape[1])
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            gsl.gsl_matrix_set(gsl_matrix.matrix, i, j, np_array[i, j])
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    np_array = np.zeros((gsl_matrix.matrix.t_rows, gsl_matrix.matrix.t_cols))
    for i in range(gsl_matrix.matrix.t_rows):
        for j in range(gsl_matrix.matrix.t_cols):
            np_array[i, j] = gsl.gsl_matrix_get(gsl_matrix.matrix, i, j)
    return np_array

def gsl_multifit_covar(jacobian, epsrel):
    covariance_matrix = GSLMatrix(jacobian.matrix.t_rows, jacobian.matrix.t_cols)
    gsl.gsl_multifit_covar(jacobian.matrix, epsrel, covariance_matrix.matrix)
    return covariance_matrix

